class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        from collections import deque

        m, n = len(mat), len(mat[0])
        q = deque()
        for i in range(m):
            row = mat[i]
            for j in range(n):
                if row[j] == 0:
                    q.append((i, j))
                else:
                    row[j] = -1
        d = 0
        while q:
            for _ in range(len(q)):
                i, j = q.popleft()
                if mat[i][j] == -1:
                    mat[i][j] = d
                nd = d + 1
                if i and mat[i - 1][j] == -1:
                    mat[i - 1][j] = nd
                    q.append((i - 1, j))
                if i + 1 < m and mat[i + 1][j] == -1:
                    mat[i + 1][j] = nd
                    q.append((i + 1, j))
                if j and mat[i][j - 1] == -1:
                    mat[i][j - 1] = nd
                    q.append((i, j - 1))
                if j + 1 < n and mat[i][j + 1] == -1:
                    mat[i][j + 1] = nd
                    q.append((i, j + 1))
            d += 1
        return mat

