class Solution:
    def countSpecialNumbers(self, n: int) -> int:
        s = str(n)
        m = len(s)

        def perm(a, b):
            r = 1
            for i in range(b):
                r *= a - i
            return r

        ans = 0
        for l in range(1, m):
            ans += 9 * perm(9, l - 1)

        used = [False] * 10
        for i, ch in enumerate(s):
            d = ord(ch) - 48
            start = 1 if i == 0 else 0
            for x in range(start, d):
                if not used[x]:
                    ans += perm(10 - (i + 1), m - i - 1)
            if used[d]:
                return ans
            used[d] = True

        return ans + 1

