class Solution:
    def finalString(self, s: str) -> str:
        ans = []
        rev = False
        for ch in s:
            if ch == "i":
                rev = not rev
            elif rev:
                ans.insert(0, ch)
            else:
                ans.append(ch)
        if rev:
            ans.reverse()
        return "".join(ans)

