class Solution:
    def gameOfLife(self, board: List[List[int]]) -> None:
        m = len(board)
        n = len(board[0]) if m else 0
        for i in range(m):
            for j in range(n):
                cnt = 0
                for x in (i - 1, i, i + 1):
                    if 0 <= x < m:
                        row = board[x]
                        for y in (j - 1, j, j + 1):
                            if (x != i or y != j) and 0 <= y < n and (row[y] & 1):
                                cnt += 1
                if board[i][j] == 1 and cnt in (2, 3) or board[i][j] == 0 and cnt == 3:
                    board[i][j] |= 2
        for i in range(m):
            for j in range(n):
                board[i][j] >>= 1

