class Solution:
    def maxSumAfterPartitioning(self, arr: List[int], k: int) -> int:
        n = len(arr)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            best = 0
            mx = 0
            lim = k if k < i else i
            for j in range(1, lim + 1):
                v = arr[i - j]
                if v > mx:
                    mx = v
                cand = dp[i - j] + mx * j
                if cand > best:
                    best = cand
            dp[i] = best
        return dp[n]

