class Solution:
    def rowAndMaximumOnes(self, mat: List[List[int]]) -> List[int]:
        best_i = 0
        best_c = -1
        for i, row in enumerate(mat):
            c = sum(row)
            if c > best_c:
                best_c = c
                best_i = i
        return [best_i, best_c]

